<?php $title='Workout complete';$workoutMode=true;$totalSets=array_sum(array_map(fn($row)=>(int)$row['working_sets'],$state['summary']));$orderChanged=(int)($state['session']['template_order_changed']??0)===1;$setsChanged=(int)($state['session']['template_sets_changed']??0)===1; ?>
<div class="mx-auto max-w-2xl"><div class="mb-6 text-center"><p class="text-6xl">✅</p><h1 class="mt-3 text-3xl font-black">Workout complete</h1><p class="mt-1 text-zinc-400"><?= e($state['session']['session_type']) ?> · <?= $totalSets ?> working sets</p></div><div class="grid gap-3 sm:grid-cols-2"><?php foreach($state['summary'] as $row): ?><div class="card"><div class="flex justify-between gap-2"><strong><?= e($row['name']) ?></strong><?php if($row['personal_record']): ?><span class="text-sm text-emerald-400">🏆 PR</span><?php endif; ?></div><p class="mt-2 text-xl font-black"><?= e($row['best_weight']??'—') ?> kg × <?= (int)$row['best_reps'] ?></p></div><?php endforeach; ?></div><form method="post" action="<?= e(route('workouts.active.finish')) ?>" class="card mt-5"><?= csrf_field() ?><label for="workout-note">Optional workout note</label><textarea id="workout-note" name="notes" rows="2" placeholder="How did it feel?"></textarea><?php if($orderChanged||$setsChanged): ?><div class="mt-4 rounded-2xl border border-violet-900/60 bg-violet-950/25 p-4"><p class="font-bold text-violet-300">Update your workout plan?</p><p class="mt-1 text-sm text-zinc-400">Your workout is saved either way. These changes only affect future sessions.</p><?php if($orderChanged): ?><label class="mt-3 flex items-center gap-3"><input class="h-5 w-5" type="checkbox" name="update_template_order" value="1"><span>Use this exercise order next time</span></label><?php endif; ?><?php if($setsChanged): ?><label class="mt-3 flex items-center gap-3"><input class="h-5 w-5" type="checkbox" name="update_template_sets" value="1"><span>Use these working-set counts next time</span></label><?php endif; ?></div><?php endif; ?><button class="btn-primary mt-4 w-full">Finish workout</button></form></div>
